```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, span_name, count(*) n, round(approx_quantile(duration,0.1)/1e6,1) p10_ms, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.9)/1e6,1) p90_ms FROM (SELECT 'abnormal' p,* FROM abnormal_traces UNION ALL SELECT 'normal',* FROM normal_traces) WHERE service_name='search' AND attr_span_kind='Client' GROUP BY ALL ORDER BY 2,1",
          "claim": "search's client spans to rate.Rate/GetRates jump from about 1.5ms median to about 1.9s; geo calls from search stay at 0.5ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, round(c.duration/1e6,1) client_ms, round(s.duration/1e6,2) rate_server_ms, round((epoch(s.time)-epoch(c.time))*1000,1) server_start_lag_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' AND s.service_name='rate' ORDER BY c.duration DESC LIMIT 15",
          "claim": "Rate's server spans take under 1ms, but start about 2.3-2.8s after search's client call began, so the delay sits before rate receives the request."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, round(sum(CASE WHEN attr_status_code='ERROR' THEN 1 ELSE 0 END)*1.0/count(*),3) err_share FROM abnormal_traces WHERE service_name IN ('search','rate') GROUP BY ALL ORDER BY 1,3",
          "claim": "Abnormal search server spans have p95 near 2.8s with no errors, and rate server spans stay near 0.9ms, so the slowness lives on search's outgoing rate calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) mean_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'abnormal' p,* FROM abnormal_traces UNION ALL SELECT 'normal',* FROM normal_traces) WHERE (service_name='frontend' AND span_name='HTTP /hotels') OR (service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Search's Nearby server spans and frontend's HTTP /hotels spans both rise to about 2s, while the other frontend HTTP routes stay near normal."
        }
      ]
    }
  ]
}
```

